sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    if (!current.active)
        return;

    var keyChanged = current.parent.changes() || current.action_type.changes() ||
        current.assigned_to.changes() || current.active.changes();
    if (!current.isNewRecord() && !keyChanged)
        return;

    var dup = new MgrHubUtils().findOpenDuplicateAction(
        current.getValue('parent'),
        current.getValue('action_type'),
        current.getValue('assigned_to'),
        current.getUniqueValue());

    if (dup) {
        gs.addErrorMessage(gs.getMessage('An open "{0}" action for {1} already exists on this request ({2}).',
            [current.action_type.getDisplayValue(),
             current.assigned_to.getDisplayValue() || gs.getMessage('no owner'),
             dup.getValue('number')]));
        current.setAbortAction(true);
    }
})(current, previous);
